use std::process::exit;

use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Params { n: u32, pad0: u32, dt: f32, pad1: f32 }

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read_write> acc: array<vec2<f32>>;

@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.n) { return; }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j = 0u; j < params.n; j = j + 1u) {
        if (j == i) { continue; }
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        a = a + d / (r2 * sqrt(r2));
    }
    acc[i] = a;
}

@compute @workgroup_size(64)
fn integrate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.n) { return; }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
"#;

fn fail(msg: &str) -> ! {
    eprintln!("{msg}");
    exit(1);
}

fn parse_input(path: &str) -> (usize, u32, f32, Vec<[f32; 2]>, Vec<[f32; 2]>) {
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| fail(&format!("read {path}: {e}")));
    let mut it = text.split_whitespace();
    let mut next = || it.next().unwrap_or_else(|| fail("unexpected end of input"));
    let count: usize = next().parse().unwrap_or_else(|_| fail("bad count"));
    let steps: u32 = next().parse().unwrap_or_else(|_| fail("bad steps"));
    let dt: f64 = next().parse().unwrap_or_else(|_| fail("bad dt"));
    let mut pos = Vec::with_capacity(count);
    let mut vel = Vec::with_capacity(count);
    for _ in 0..count {
        let mut f = [0f64; 4];
        for v in f.iter_mut() {
            *v = next().parse().unwrap_or_else(|_| fail("bad number"));
        }
        pos.push([f[0] as f32, f[1] as f32]);
        vel.push([f[2] as f32, f[3] as f32]);
    }
    (count, steps, dt as f32, pos, vel)
}

fn main() {
    let path = std::env::args().nth(1).unwrap_or_else(|| fail("usage: particles <file>"));
    let (n, steps, dt, pos, vel) = parse_input(&path);

    let (final_pos, final_vel) = if n == 0 { (pos, vel) } else { simulate(n, steps, dt, &pos, &vel) };

    let nf = n as f64;
    let (mut cx, mut cy, mut mx, mut my, mut ke) = (0f64, 0f64, 0f64, 0f64, 0f64);
    for (p, v) in final_pos.iter().zip(&final_vel) {
        let (px, py, vx, vy) = (p[0] as f64, p[1] as f64, v[0] as f64, v[1] as f64);
        cx += px;
        cy += py;
        mx += vx;
        my += vy;
        ke += (vx * vx + vy * vy) / 2.0;
    }
    cx /= nf;
    cy /= nf;
    let mut sq = 0f64;
    for p in &final_pos {
        let (dx, dy) = (p[0] as f64 - cx, p[1] as f64 - cy);
        sq += dx * dx + dy * dy;
    }
    let spread = (sq / nf).sqrt();
    println!("CENTER {cx:.6} {cy:.6}");
    println!("MOMENTUM {mx:.6} {my:.6}");
    println!("KINETIC {ke:.6}");
    println!("SPREAD {spread:.6}");
}

fn simulate(n: usize, steps: u32, dt: f32, pos: &[[f32; 2]], vel: &[[f32; 2]]) -> (Vec<[f32; 2]>, Vec<[f32; 2]>) {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .unwrap_or_else(|e| fail(&format!("no GPU adapter: {e}")));
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .unwrap_or_else(|e| fail(&format!("device: {e}")));

    let size = (n * 8) as u64;
    let usage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC;
    let pos_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(pos),
        usage,
    });
    let vel_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(vel),
        usage,
    });
    let acc_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage,
        mapped_at_creation: false,
    });
    let mut params = [0u8; 16];
    params[0..4].copy_from_slice(&(n as u32).to_ne_bytes());
    params[8..12].copy_from_slice(&dt.to_ne_bytes());
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: &params,
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let read_pos = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let read_vel = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let make = |entry: &str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: None,
            layout: None,
            module: &module,
            entry_point: Some(entry),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let accel = make("accelerate");
    let integ = make("integrate");
    let entries = [
        wgpu::BindGroupEntry { binding: 0, resource: params_buf.as_entire_binding() },
        wgpu::BindGroupEntry { binding: 1, resource: pos_buf.as_entire_binding() },
        wgpu::BindGroupEntry { binding: 2, resource: vel_buf.as_entire_binding() },
        wgpu::BindGroupEntry { binding: 3, resource: acc_buf.as_entire_binding() },
    ];
    let bg = |p: &wgpu::ComputePipeline| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &p.get_bind_group_layout(0),
            entries: &entries,
        })
    };
    let bg_accel = bg(&accel);
    let bg_integ = bg(&integ);

    let groups = (n as u32).div_ceil(64);
    // Submit in batches so a single command buffer stays small.
    let mut remaining = steps;
    while remaining > 0 {
        let batch = remaining.min(50);
        remaining -= batch;
        let mut enc = device.create_command_encoder(&Default::default());
        for _ in 0..batch {
            {
                let mut pass = enc.begin_compute_pass(&Default::default());
                pass.set_pipeline(&accel);
                pass.set_bind_group(0, &bg_accel, &[]);
                pass.dispatch_workgroups(groups, 1, 1);
            }
            {
                let mut pass = enc.begin_compute_pass(&Default::default());
                pass.set_pipeline(&integ);
                pass.set_bind_group(0, &bg_integ, &[]);
                pass.dispatch_workgroups(groups, 1, 1);
            }
        }
        queue.submit([enc.finish()]);
    }
    let mut enc = device.create_command_encoder(&Default::default());
    enc.copy_buffer_to_buffer(&pos_buf, 0, &read_pos, 0, size);
    enc.copy_buffer_to_buffer(&vel_buf, 0, &read_vel, 0, size);
    queue.submit([enc.finish()]);

    let read = |buf: &wgpu::Buffer| -> Vec<[f32; 2]> {
        buf.slice(..).map_async(wgpu::MapMode::Read, |r| r.expect("map failed"));
        device.poll(wgpu::PollType::wait_indefinitely()).expect("poll failed");
        let data = buf.slice(..).get_mapped_range();
        let v: Vec<[f32; 2]> = bytemuck::cast_slice(&data).to_vec();
        drop(data);
        buf.unmap();
        v
    };
    (read(&read_pos), read(&read_vel))
}
