    let mut next = || it.next().unwrap_or_else(|| fail("unexpected end of input"));
    let count: usize = next().parse().unwrap_or_else(|_| fail("bad count"));
    let steps: u32 = next().parse().unwrap_or_else(|_| fail("bad steps"));
